package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.*;import cl.nexbyte.siger.institucional.identidad.*;import cl.nexbyte.siger.institucional.documental.*;import cl.nexbyte.siger.institucional.formulario.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.nio.file.*;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.SpringBootConfiguration;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.test.annotation.DirtiesContext;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockHttpSession;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;

@SpringBootTest(classes=CuarentenaHttpTest.Application.class,properties={"institucional.nucleo.habilitado=true","institucional.identidad.habilitada=true","institucional.documental.habilitada=true"}) @AutoConfigureMockMvc @DirtiesContext
class CuarentenaHttpTest {
 @SpringBootConfiguration @EnableAutoConfiguration @Import({SeguridadInstitucional.class,NucleoController.class,CuarentenaDocumentalController.class,DocumentosRequerimientoController.class,ErroresTecnicos.class,JsonEstricto.class,Fixture.class})static class Application{}
 @Configuration static class Fixture {
  @Bean(destroyMethod="close") CuarentenaFixture fixture()throws Exception{return new CuarentenaFixture(Files.createTempDirectory("cuarentena-http-"));}
  @Bean IdentidadInstitucional ids(CuarentenaFixture f){return f.x.f.ids;}@Bean CatalogoLaboratorio cat(CuarentenaFixture f){return f.x.f.cat;}@Bean NucleoInstitucional core(CuarentenaFixture f){return f.x.f.core;}
  @Bean(destroyMethod="") BaseJdbc db(CuarentenaFixture f){return f.x.d.db;}@Bean(destroyMethod="") ArchivoInstitucional files(CuarentenaFixture f){return f.x.files;}@Bean RecepcionInstitucionalJdbc receiver(CuarentenaFixture f){return f.x.d.recepcion;}@Bean DocumentosRequerimiento documentos(CuarentenaFixture f){return f.x.docs;}@Bean CuarentenaDocumental cuarentena(CuarentenaFixture f){return f.q;}
  @Bean VisorDocumento visor(CuarentenaFixture f){return new VisorDocumento(f.x.d.db,f.x.files,p->true,f.x.inspector,new ProcesamientoDocumental.Renderizador(){public int paginas(Path p){throw new AssertionError();}public byte[] pagina(Path p,int n){throw new AssertionError();}},f.x.clock);}
  @Bean AutoridadesInstitucionales authority(CuarentenaFixture f){return f.x.f.f.autoridades;}@Bean HabilitacionNucleo gate(){return new HabilitacionNucleo(HabilitacionNucleoTest.valid());}@Bean Clock relojLimitesLogin(){return Clock.systemUTC();}
 }
 @Autowired MockMvc http;@Autowired CuarentenaFixture f;
 MockHttpSession login(String actor)throws Exception{String name=f.x.d.db.sql.queryForObject("SELECT username FROM staff_account WHERE actor_id=?",String.class,actor);var s=new MockHttpSession();http.perform(post("/nucleo/login").secure(true).session(s).with(csrf()).param("username",name).param("password",f.x.f.passwords.get(name))).andExpect(status().isNoContent());return s;}
 @Test void tiAislaSinLecturaYLiberacionExigeSesionIndependienteEIntegridad()throws Exception{
  var x=f.x;var d=x.cargar();var ti=login(x.f.ti);var peer=login(f.peer);var owner=login(x.f.profA);String path="/nucleo/ti/cuarentena-documental",body=x.d.mapper.writeValueAsString(f.solicitud(d));UUID key=x.key();
  http.perform(get(path).secure(true).session(owner)).andExpect(status().isForbidden());http.perform(post(path).secure(true).session(ti).header("Idempotency-Key",key).header("X-Siger-Actor",x.f.ti).contentType("application/json").content(body)).andExpect(status().isForbidden());
  var response=http.perform(post(path).secure(true).session(ti).with(csrf()).header("Idempotency-Key",key).header("X-Siger-Actor",x.f.ti).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.documento").value(d.id().toString())).andExpect(jsonPath("$.nombre").doesNotExist()).andExpect(jsonPath("$.caso").doesNotExist()).andExpect(jsonPath("$.verificable").value(false)).andReturn();String hold=x.d.mapper.readTree(response.getResponse().getContentAsString()).path("id").asString(),docs="/nucleo/requerimientos/"+x.req+"/documentos-gestion";
  http.perform(get(docs).secure(true).session(ti)).andExpect(status().isNotFound());http.perform(get(docs).secure(true).session(owner)).andExpect(status().isOk()).andExpect(jsonPath("$.documentos[0].cuarentena").value(true)).andExpect(jsonPath("$.documentos[0].consultable").value(false));http.perform(get(docs+"/"+d.id()+"/original").secure(true).session(owner)).andExpect(status().isLocked());
  String review=x.d.mapper.writeValueAsString(new CuarentenaDocumental.Verificar(0,"Revisión independiente sintética"));http.perform(post(path+"/"+hold+"/verificar").secure(true).session(peer).with(csrf()).header("Idempotency-Key",x.key()).header("X-Siger-Actor",x.f.ti).contentType("application/json").content(review)).andExpect(status().isConflict());http.perform(post(path+"/"+hold+"/verificar").secure(true).session(peer).with(csrf()).header("Idempotency-Key",x.key()).contentType("application/json").content(review)).andExpect(status().isBadRequest());http.perform(post(path+"/"+hold+"/verificar").secure(true).session(ti).with(csrf()).header("Idempotency-Key",x.key()).header("X-Siger-Actor",x.f.ti).contentType("application/json").content(review)).andExpect(status().isForbidden());
  http.perform(post(path+"/"+hold+"/verificar").secure(true).session(peer).with(csrf()).header("Idempotency-Key",x.key()).header("X-Siger-Actor",f.peer).contentType("application/json").content(review)).andExpect(status().isOk()).andExpect(jsonPath("$.estado").value("LIBERADO"));
  http.perform(get(docs).secure(true).session(owner)).andExpect(status().isOk()).andExpect(jsonPath("$.documentos[0].consultable").value(true)).andExpect(jsonPath("$.documentos[0].cuarentena").value(false));http.perform(get(docs).secure(true).session(peer)).andExpect(status().isNotFound());
 }
}
